import { ElevenLabsClient } from '@elevenlabs/elevenlabs-js';
import type { Voice } from '#lib/types.ts';
import { elevenLabsApiKey } from './env.ts';
import { ProviderError } from './http.ts';

// Flash is the lowest-latency model, so playback starts while the rest still streams.
const MODEL_ID = 'eleven_flash_v2_5';
const MAX_RETRIES = 2;

const VOICE_IDS: Record<Voice, string> = {
	female: 'TODO',
	male: 'TODO'
};

/**
 * Streams the narration of a story in the chosen voice.
 * @param text The story paragraph.
 * @param voice Narrator voice.
 * @returns MP3 audio as it is synthesized.
 * @throws {ProviderError} When ElevenLabs fails after the SDK's retries.
 */
export async function narrate(text: string, voice: Voice): Promise<ReadableStream<Uint8Array>> {
	try {
		return await new ElevenLabsClient({
			apiKey: elevenLabsApiKey(),
			maxRetries: MAX_RETRIES
		}).textToSpeech.stream(VOICE_IDS[voice], { text, modelId: MODEL_ID });
	} catch (e) {
		throw new ProviderError('Narrating the story failed', { cause: e });
	}
}

import { apiError, providerFailed } from '#lib/server/http.ts';
import { narrate } from '#lib/server/narration.ts';
import { VOICES } from '#lib/types.ts';
import { z } from 'zod';
import type { RequestHandler } from './$types';

// A story runs 100 to 170 words; the cap keeps this from narrating arbitrary text at our cost.
const MAX_CHARS = 1_500;

const querySchema = z.object({
	text: z.string().trim().min(1).max(MAX_CHARS),
	voice: z.enum(VOICES)
});

/**
 * Streams a story read aloud. GET, so an `<audio>` element can play it as it arrives.
 * @param event Request with `text` and `voice` query parameters.
 * @param event.url The request URL.
 * @returns MP3 audio, or an `ApiError`.
 */
export const GET: RequestHandler = async ({ url }) => {
	const query = querySchema.safeParse(Object.fromEntries(url.searchParams));
	if (!query.success) return apiError('invalid_input', 'Send a story and a voice.', 400);
	try {
		return new Response(await narrate(query.data.text, query.data.voice), {
			headers: { 'content-type': 'audio/mpeg' }
		});
	} catch (e) {
		return providerFailed(e);
	}
};

